   "orig": "另一个也许有朝一日会在物理理论里占一席之地的想法，是范畴论以及它的推广 n-范畴论。范畴论由 Samuel Eilenberg 与 Saunders Mac Lane 于 1945 年提出，是一种极其一般的代数形式框架，底座是几个非常原始（也令人困惑）的抽象概念，最初由代数拓扑的思想催生（行内人常把它的手法戏称为「抽象废话」）。它的基本材料不过是连接「对象」的「箭头」，威力因此显得很不相称；外观又很「组合式」，与本节提到的其他想法相似。范畴论推广到 n-范畴论，反映的是「同伦」如何细化「同调」概念（7.2 节曾简述）。范畴论已经给扭量理论提供过输入（与 33.9 节有关）；n-范畴论则与圈、链环、自旋泡沫（32.7 节）和 q-变形结构（32.5 节）都有牵连。若这些概念在 21 世纪物理学里真起了取代常规时空观念的作用，我不会太吃惊。",
